// Live vs static collections (tiny fake DOM). Time O(n) per query.
class Box {
  constructor() { this.kids = []; }
  add(cls) { this.kids.push({ cls }); }
  remove(el) { this.kids.splice(this.kids.indexOf(el), 1); }
  // live: re-reads the tree each time it is used, like HTMLCollection
  liveByClass(c) { const self = this; return { get length() { return self.kids.filter(k => k.cls === c).length; } }; }
  // static: snapshot taken now, like querySelectorAll
  staticByClass(c) { const snap = this.kids.filter(k => k.cls === c); return { length: snap.length }; }
}
const box = new Box();
box.add("item"); box.add("item"); box.add("other");
const live = box.liveByClass("item");
const snap = box.staticByClass("item");
