// Capture then target then bubble on a tiny tree. Time O(depth).
function node(name, parent) { return { name, parent, ls: [] }; }
function on(n, type, fn, capture) { n.ls.push({ type, fn, capture: !!capture }); }
function dispatch(target, type) {
  const path = [];
  for (let n = target.parent; n; n = n.parent) path.unshift(n); // root ... parent
  const run = (n, capture) => n.ls.forEach(l => {
    if (l.type === type && l.capture === capture) l.fn({ target: target.name, currentTarget: n.name });
  });
  path.forEach(n => run(n, true));      // 1) capturing: top down
  run(target, true); run(target, false); // 2) at target
  path.slice().reverse().forEach(n => run(n, false)); // 3) bubbling: bottom up
}
