// Event delegation: one listener on the list, closest() finds the item.
function el(tag, cls, parent) {
  const e = { tag, cls, parent, kids: [] };
  if (parent) parent.kids.push(e);
  return e;
}
function closest(e, tag, stop) { // walk up until a match or the container
  for (; e; e = e.parent) { if (e.tag === tag) return e; if (e === stop) return null; }
  return null;
}
