// debounce vs throttle with a fake clock so the output is exact.
let now = 0, timers = [];
const setT = (fn, ms) => { const t = { fn, at: now + ms }; timers.push(t); return t; };
const clearT = t => { timers = timers.filter(x => x !== t); };
function advance(to) { // run timers due up to time `to`
  for (;;) {
    timers.sort((a, b) => a.at - b.at);
    if (!timers.length || timers[0].at > to) break;
    const t = timers.shift(); now = t.at; t.fn();
  }
  now = to;
}
function debounce(fn, wait) {
  let timer;
  return (...args) => { clearT(timer); timer = setT(() => fn(...args), wait); }; // restart each call
}
function throttle(fn, wait) {
  let last = -Infinity;
  return (...args) => { if (now - last >= wait) { last = now; fn(...args); } }; // at most once per wait
}
const d = debounce(v => console.log("debounced ran with " + v + " at t=" + now), 100);
const t = throttle(v => console.log("throttled ran with " + v + " at t=" + now), 100);
for (let i = 0; i <= 5; i++) { // a call every 40ms: t=0,40,...,200
  advance(i * 40); d(i); t(i);
}
