// Simple EventEmitter: copy before emit, once removed before call.
class Emitter {
  constructor() { this.map = new Map(); }
  on(name, fn, once = false) {
    if (!this.map.has(name)) this.map.set(name, []);
    const rec = { fn, once };
    this.map.get(name).push(rec);
    return () => this.off(name, fn); // unsubscribe function
  }
  once(name, fn) { return this.on(name, fn, true); }
  off(name, fn) {
    const a = this.map.get(name); if (!a) return;
    const i = a.findIndex(r => r.fn === fn); if (i >= 0) a.splice(i, 1);
    if (!a.length) this.map.delete(name); // avoid leaks
  }
  emit(name, ...args) {
    const a = this.map.get(name); if (!a) return false;
    for (const r of [...a]) { // iterate a copy: listeners may change the list
      if (r.once) this.off(name, r.fn); // remove first so re-entrant emit cannot repeat it
      r.fn(...args);
    }
    return true;
  }
}
