// Microtask timing: real click vs script click (simulated queue).
function run(fromUser) {
  const micro = [], log = [];
  const drain = () => { while (micro.length) micro.shift()(); };
  const listeners = [
    () => { log.push("first"); micro.push(() => log.push("micro")); },
    () => log.push("second"),
  ];
  for (const l of listeners) {
    l();
    if (fromUser) drain(); // stack is empty after each listener, so a checkpoint runs
  }
  // script click: the caller's code is still running here
  log.push("script continues");
  drain();                // microtasks run when the whole script finishes
  return log.join(", ");
}
console.log("real user click:   " + run(true));
console.log("button.click():    " + run(false));

// Layout thrashing: read/write interleaved vs batched (counts forced layouts).
let layouts = 0, dirty = true;
function makeEl() {
  let h = 10;
  return {
    get offsetHeight() { if (dirty) { layouts++; dirty = false; } return h; }, // read forces layout if dirty
    setHeight(v) { h = v; dirty = true; },                                      // write invalidates layout
  };
}
const els = Array.from({ length: 100 }, makeEl);
layouts = 0;
for (const e of els) e.setHeight(e.offsetHeight + 1); // read, write, read, write...
console.log("interleaved: " + layouts + " layouts for " + els.length + " elements");
layouts = 0; dirty = true;
const heights = els.map(e => e.offsetHeight);         // all reads first
els.forEach((e, i) => e.setHeight(heights[i] + 1));   // then all writes
console.log("batched:     " + layouts + " layout for " + els.length + " elements");
